import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 평가 점수는 교육대상자의 평가항목별 점수 평균(반올림)으로 보인다.
// 가정: 교육 기간 조건은 차수의 시작일 >= 시작, 종료일 <= 종료 로 거른다.
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function fail(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function textOrNull(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  return String(value);
}

function integerOrNull(value: unknown, label: string): string | null {
  const text = textOrNull(value);
  if (text === null) {
    return null;
  }
  if (!/^\d+$/.test(text)) {
    throw fail(label + ' 형식이 올바르지 않습니다.');
  }
  return text;
}

function dateOrNull(value: unknown, label: string): string | null {
  const text = textOrNull(value);
  if (text === null) {
    return null;
  }
  if (!DATE_PATTERN.test(text)) {
    throw fail(label + ' 형식이 올바르지 않습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr01505Controller {
  @Get('/edu-status')
  async listEduStatus(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '인사 담당자');
    const query = checks.queryOf(req.query);
    const startDate = dateOrNull(query['startDate'], '교육 기간 시작');
    const endDate = dateOrNull(query['endDate'], '교육 기간 종료');
    const eduCourseId = integerOrNull(query['eduCourseId'], '교육과정');
    const eduSessionId = integerOrNull(query['eduSessionId'], '교육차수');
    const employeeId = integerOrNull(query['employeeId'], '교육대상자');
    const departmentId = integerOrNull(query['departmentId'], '주부서');
    const pageText = integerOrNull(query['page'], '쪽');
    const sizeText = integerOrNull(query['size'], '쪽 크기');
    const page = pageText === null ? 0 : Number(pageText);
    let size = sizeText === null ? DEFAULT_SIZE : Number(sizeText);
    if (size < 1) {
      throw fail('쪽 크기는 1 이상이어야 합니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const params = {
      startDate,
      endDate,
      eduCourseId,
      eduSessionId,
      employeeId,
      departmentId,
      size,
      offset: page * size,
    };
    const where = `
      WHERE (CAST(:startDate AS date) IS NULL OR s.start_date >= CAST(:startDate AS date))
        AND (CAST(:endDate AS date) IS NULL OR s.end_date <= CAST(:endDate AS date))
        AND (CAST(:eduCourseId AS bigint) IS NULL OR c.edu_course_id = CAST(:eduCourseId AS bigint))
        AND (CAST(:eduSessionId AS bigint) IS NULL OR s.edu_session_id = CAST(:eduSessionId AS bigint))
        AND (CAST(:employeeId AS bigint) IS NULL OR a.employee_id = CAST(:employeeId AS bigint))
        AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))`;
    const from = `
      FROM edu_attendee a
      JOIN edu_session s ON s.edu_session_id = a.edu_session_id
      JOIN edu_course c ON c.edu_course_id = s.edu_course_id
      JOIN employee e ON e.employee_id = a.employee_id
      LEFT JOIN edu_application ap ON ap.edu_application_id = a.edu_application_id`;
    return transaction(async (db) => {
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total"' + from + where,
        params,
      );
      const total = Number(countRows[0]['total']);
      const items = await db.query(
        `SELECT c.course_name AS "courseName",
          s.session_no AS "sessionNo",
          ap.status AS "applicationStatus",
          a.employee_id AS "employeeId",
          (SELECT CAST(ROUND(AVG(ev.score)) AS integer)
             FROM edu_evaluation ev
            WHERE ev.edu_attendee_id = a.edu_attendee_id) AS "score"` +
          from +
          where +
          `
      ORDER BY c.course_name, s.session_no, a.employee_id
      LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      return { items, page, size, total };
    });
  }
}

