import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  RefName,
  call,
  useData,
} from '../kit';
import type { Column, Page, PageProps, Row } from '../kit';

const SIZE = 20;

const EMPTY_FILTER: Row = {
  startDate: '',
  endDate: '',
  eduCourseId: '',
  eduSessionId: '',
  employeeId: '',
  departmentId: '',
};

export default function FnSfr01505Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>(EMPTY_FILTER);
  const [applied, setApplied] = useState<Row>(EMPTY_FILTER);
  const [page, setPage] = useState(0);

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/edu-status', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );

  function change(key: string, value: unknown) {
    setDraft({ ...draft, [key]: value });
  }

  function search() {
    if (draft.startDate && draft.endDate && String(draft.startDate) > String(draft.endDate)) {
      notify('교육 기간 시작이 종료보다 늦을 수 없습니다.');
      return;
    }
    setPage(0);
    setApplied({ ...draft });
  }

  function reset() {
    setDraft(EMPTY_FILTER);
    setApplied(EMPTY_FILTER);
    setPage(0);
  }

  const columns: Column[] = [
    { key: 'courseName', label: '교육과정명' },
    { key: 'sessionNo', label: '차수' },
    {
      key: 'applicationStatus',
      label: '신청 상태',
      render: (row) => <Badge value={row.applicationStatus} />,
    },
    {
      key: 'employeeId',
      label: '교육대상자',
      render: (row) => <RefName table="employee" role={role} value={row.employeeId} />,
    },
    {
      key: 'score',
      label: '평가 점수',
      render: (row) => <Num value={row.score} />,
    },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Num value={data ? data.total : 0} />
      </section>
      <section className="box span-12">
        <h2>교육 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="교육 기간 시작">
            <DateInput value={draft.startDate} onChange={(v) => change('startDate', v)} />
          </Field>
          <Field label="교육 기간 종료">
            <DateInput value={draft.endDate} onChange={(v) => change('endDate', v)} />
          </Field>
          <Field label="교육과정 ID">
            <LookupSelect
              table="edu_course"
              role={role}
              value={draft.eduCourseId}
              onChange={(v) => change('eduCourseId', v)}
            />
          </Field>
          <Field label="교육차수 ID">
            <LookupSelect
              table="edu_session"
              role={role}
              value={draft.eduSessionId}
              onChange={(v) => change('eduSessionId', v)}
            />
          </Field>
          <Field label="교육대상자">
            <LookupSelect
              table="employee"
              role={role}
              value={draft.employeeId}
              onChange={(v) => change('employeeId', v)}
            />
          </Field>
          <Field label="주부서">
            <LookupSelect
              table="department"
              role={role}
              value={draft.departmentId}
              onChange={(v) => change('departmentId', v)}
            />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0} />
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={columns}
          rows={data ? data.items : []}
          empty={loading ? '불러오는 중입니다.' : '조회 결과가 없습니다.'}
        />
        <Pager
          page={page}
          size={SIZE}
          total={data ? data.total : 0}
          onPage={setPage}
        />
      </section>
    </div>
  );
}
